alter table public.subscriptions add column if not exists primary_walker_id uuid references public.walkers(id);
create table if not exists public.walker_leave_requests(
 id uuid primary key default gen_random_uuid(),walker_id uuid not null references public.walkers(id) on delete cascade,
 start_date date not null,end_date date not null,reason text not null,
 status text not null default 'pending' check(status in ('pending','approved','rejected')),
 reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text,created_at timestamptz not null default now(),
 constraint walker_leave_dates_valid check(end_date>=start_date));
create index if not exists walker_leave_requests_walker_dates_idx on public.walker_leave_requests(walker_id,start_date,end_date);
alter table public.walker_leave_requests enable row level security;
drop policy if exists walker_leave_read_own_or_admin on public.walker_leave_requests;
create policy walker_leave_read_own_or_admin on public.walker_leave_requests for select to authenticated using(walker_id=(select auth.uid()) or private.is_admin());
grant select on public.walker_leave_requests to authenticated;
create or replace function public.walker_submit_leave(p_start_date date,p_end_date date,p_reason text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not exists(select 1 from public.walkers where id=auth.uid() and is_active and verification_status='approved') then raise exception 'Approved active Walker required'; end if; if p_start_date<=(now() at time zone 'Asia/Kolkata')::date-1 or p_end_date<p_start_date then raise exception 'Choose a valid future leave period'; end if; if length(btrim(coalesce(p_reason,'')))<5 or length(p_reason)>1000 then raise exception 'Leave reason must be 5–1000 characters'; end if; if exists(select 1 from public.walker_leave_requests where walker_id=auth.uid() and status in ('pending','approved') and daterange(start_date,end_date,'[]') && daterange(p_start_date,p_end_date,'[]')) then raise exception 'A leave request already overlaps these dates'; end if; insert into public.walker_leave_requests(walker_id,start_date,end_date,reason) values(auth.uid(),p_start_date,p_end_date,btrim(p_reason)) returning id into v_id; return v_id; end $$;
create or replace function public.admin_review_leave(p_request_id uuid,p_approve boolean,p_note text default null) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; update public.walker_leave_requests set status=case when p_approve then 'approved' else 'rejected' end,reviewed_by=auth.uid(),reviewed_at=now(),review_note=nullif(btrim(p_note),'') where id=p_request_id and status='pending'; if not found then raise exception 'Pending leave request not found'; end if; end $$;
create or replace function public.admin_assign_booking(p_booking_id uuid,p_walker_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_customer uuid; v_dog uuid; v_subscription uuid; v_scheduled timestamptz; v_duration smallint; v_primary uuid; v_count integer; begin if not private.is_admin() then raise exception 'Admin access required'; end if; if not exists(select 1 from public.walkers w join public.profiles p on p.id=w.id where w.id=p_walker_id and p.role='walker' and w.is_active and w.verification_status='approved') then raise exception 'Walker must be approved and active'; end if; select customer_id,dog_id,subscription_id,scheduled_at,duration_minutes into v_customer,v_dog,v_subscription,v_scheduled,v_duration from public.bookings where id=p_booking_id and status='requested' and walker_id is null for update; if not found then raise exception 'Booking unavailable for assignment'; end if; if exists(select 1 from public.walker_leave_requests where walker_id=p_walker_id and status='approved' and v_scheduled::date between start_date and end_date) then raise exception 'Selected walker is on approved leave for this booking date'; end if; if exists(select 1 from public.bookings b where b.walker_id=p_walker_id and b.status in ('assigned','accepted','arrived','in_progress','end_pending') and b.scheduled_at<v_scheduled+make_interval(mins=>v_duration+30) and b.scheduled_at+make_interval(mins=>b.duration_minutes+30)>v_scheduled) then raise exception 'Walker has a conflicting walk or travel buffer at this time'; end if; if v_subscription is not null then select primary_walker_id into v_primary from public.subscriptions where id=v_subscription for update; if v_primary is null then update public.subscriptions set primary_walker_id=p_walker_id where id=v_subscription; elsif v_primary<>p_walker_id then raise exception 'This subscription already has a primary walker. Use approved backup assignment for leave only'; end if; end if; select count(distinct b.dog_id) into v_count from public.bookings b where b.walker_id=p_walker_id and b.status in ('assigned','accepted','arrived','in_progress','end_pending') and b.scheduled_at>=now()-interval '1 day'; if v_count>=10 and not exists(select 1 from public.bookings b where b.walker_id=p_walker_id and b.dog_id=v_dog and b.status in ('assigned','accepted','arrived','in_progress','end_pending')) then raise exception 'Walker capacity of 10 dogs reached'; end if; update public.bookings set walker_id=p_walker_id,status='assigned',updated_at=now() where id=p_booking_id; insert into public.walk_events(booking_id,actor_id,event_type,note) values(p_booking_id,auth.uid(),'assigned','Admin assigned primary walker'); end $$;
create or replace function public.admin_assign_backup_booking(p_booking_id uuid,p_backup_walker_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare v_primary uuid; v_subscription uuid; v_dog uuid; v_scheduled timestamptz; v_duration smallint; v_count integer; begin if not private.is_admin() then raise exception 'Admin access required'; end if; if length(btrim(coalesce(p_reason,'')))<5 or length(p_reason)>1000 then raise exception 'Backup reason is required'; end if; select walker_id,subscription_id,dog_id,scheduled_at,duration_minutes into v_primary,v_subscription,v_dog,v_scheduled,v_duration from public.bookings where id=p_booking_id and status='assigned' and scheduled_at>now() for update; if not found or v_subscription is null then raise exception 'Only future assigned subscription bookings can use backup assignment'; end if; if not exists(select 1 from public.subscriptions where id=v_subscription and primary_walker_id=v_primary) then raise exception 'Current assigned Walker is not the subscription primary'; end if; if not exists(select 1 from public.walker_leave_requests where walker_id=v_primary and status='approved' and v_scheduled::date between start_date and end_date) then raise exception 'Backup assignment requires approved primary Walker leave'; end if; if not exists(select 1 from public.walkers w join public.profiles p on p.id=w.id where w.id=p_backup_walker_id and p.role='walker' and w.is_active and w.verification_status='approved') then raise exception 'Backup Walker must be approved and active'; end if; if exists(select 1 from public.walker_leave_requests where walker_id=p_backup_walker_id and status='approved' and v_scheduled::date between start_date and end_date) then raise exception 'Backup Walker is on approved leave'; end if; if exists(select 1 from public.bookings b where b.walker_id=p_backup_walker_id and b.status in ('assigned','accepted','arrived','in_progress','end_pending') and b.scheduled_at<v_scheduled+make_interval(mins=>v_duration+30) and b.scheduled_at+make_interval(mins=>b.duration_minutes+30)>v_scheduled) then raise exception 'Backup Walker has a conflicting walk or travel buffer'; end if; select count(distinct b.dog_id) into v_count from public.bookings b where b.walker_id=p_backup_walker_id and b.status in ('assigned','accepted','arrived','in_progress','end_pending') and b.scheduled_at>=now()-interval '1 day'; if v_count>=10 and not exists(select 1 from public.bookings b where b.walker_id=p_backup_walker_id and b.dog_id=v_dog and b.status in ('assigned','accepted','arrived','in_progress','end_pending')) then raise exception 'Backup Walker capacity of 10 dogs reached'; end if; update public.bookings set walker_id=p_backup_walker_id,updated_at=now() where id=p_booking_id; insert into public.walk_events(booking_id,actor_id,event_type,note) values(p_booking_id,auth.uid(),'backup_assigned','Approved leave backup; primary='||v_primary::text||'; reason='||btrim(p_reason)); end $$;
revoke all on function public.walker_submit_leave(date,date,text) from public,anon;
revoke all on function public.admin_review_leave(uuid,boolean,text) from public,anon;
revoke all on function public.admin_assign_backup_booking(uuid,uuid,text) from public,anon;
revoke all on function public.admin_assign_booking(uuid,uuid) from public,anon;
grant execute on function public.walker_submit_leave(date,date,text) to authenticated;
grant execute on function public.admin_review_leave(uuid,boolean,text) to authenticated;
grant execute on function public.admin_assign_backup_booking(uuid,uuid,text) to authenticated;
grant execute on function public.admin_assign_booking(uuid,uuid) to authenticated;